{
  "$id": "https://skogai.se/schemas/defs.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Shared schema definitions",
  "$defs": {
    "type": {
      "type": "string",
      "enum": ["router", "workflow", "reference", "template", "script", "lesson", "pattern", "decision"]
    },
    "variant": {
      "type": "string",
      "enum": ["skill", "agents", "claude", "simple-skill", "nested-router", "standalone", "knowledge"]
    },
    "status": {
      "type": "string",
      "enum": ["active", "automated", "deprecated", "archived", "draft"]
    },
    "slug": {
      "type": "string",
      "pattern": "^[a-z0-9]+(?:[._-][a-z0-9]+)*$"
    },
    "path": {
      "type": "string",
      "minLength": 1
    },
    "tag": {
      "type": "string",
      "pattern": "^[a-z0-9]+(?:[-_:][a-z0-9]+)*$"
    },
    "xmlSectionName": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9_]*$"
    },
    "heading": {
      "type": "object",
      "required": ["level", "title"],
      "properties": {
        "level": {
          "type": "integer",
          "minimum": 1,
          "maximum": 6
        },
        "title": {
          "type": "string",
          "minLength": 1
        },
        "anchor": {
          "type": "string"
        }
      },
      "additionalProperties": false
    },
    "link": {
      "type": "object",
      "required": ["kind", "target"],
      "properties": {
        "kind": {
          "type": "string",
          "enum": ["wiki", "path", "heading", "url", "asset", "anchor"]
        },
        "target": {
          "type": "string",
          "minLength": 1
        },
        "label": {
          "type": "string"
        }
      },
      "additionalProperties": false
    },
    "xmlSection": {
      "type": "object",
      "required": ["kind", "name"],
      "properties": {
        "kind": {
          "description": "Surface format the section was authored in. Not semantically meaningful on its own — `name` is what schemas validate against, so an <objective> tag and a '## Purpose' heading normalized to name 'objective' are equivalent.",
          "type": "string",
          "enum": ["xml", "heading", "codeblock"]
        },
        "name": {
          "$ref": "#/$defs/xmlSectionName"
        },
        "content": {
          "type": "string"
        },
        "items": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "table": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": {
              "type": ["string", "number", "boolean", "null"]
            }
          }
        }
      },
      "additionalProperties": false,
      "anyOf": [
        { "required": ["content"] },
        { "required": ["items"] },
        { "required": ["table"] }
      ]
    }
  }
}
{
  "$id": "https://skogai.se/schemas/frontmatter.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Skogai frontmatter",
  "type": "object",
  "required": ["type"],
  "properties": {
    "name": {
      "$ref": "defs.schema.json#/$defs/slug"
    },
    "title": {
      "type": "string",
      "minLength": 1
    },
    "description": {
      "type": "string",
      "minLength": 1
    },
    "type": {
      "$ref": "defs.schema.json#/$defs/type"
    },
    "variant": {
      "$ref": "defs.schema.json#/$defs/variant"
    },
    "status": {
      "$ref": "defs.schema.json#/$defs/status"
    },
    "version": {
      "type": ["integer", "string"],
      "minimum": 1
    },
    "permalink": {
      "type": "string",
      "minLength": 1
    },
    "tags": {
      "type": "array",
      "items": {
        "$ref": "defs.schema.json#/$defs/tag"
      },
      "uniqueItems": true
    },
    "match": {
      "type": "object",
      "properties": {
        "keywords": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          },
          "minItems": 1,
          "uniqueItems": true
        },
        "tools": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          },
          "uniqueItems": true
        }
      },
      "required": ["keywords"],
      "additionalProperties": false
    }
  },
  "additionalProperties": true
}

